import{_ as o,C as s,o as l,c as r,j as e,a as p,G as n,a3 as c}from"./chunks/framework.Bvm_liKL.js";const v=JSON.parse('{"title":"配置文件与数据目录","description":"ICC-CE 的配置文件、墨迹存档、日志与崩溃报告分别存放在哪里","frontmatter":{"title":"配置文件与数据目录","description":"ICC-CE 的配置文件、墨迹存档、日志与崩溃报告分别存放在哪里"},"headers":[],"relativePath":"cn/guide/files-and-data.md","filePath":"cn/guide/files-and-data.md"}'),d={name:"cn/guide/files-and-data.md"};function u(h,a,b,g,m,_){const t=s("ArticleMetadata"),i=s("UnderConstruction");return l(),r("div",null,[a[0]||(a[0]=e("h1",{id:"配置文件与数据目录",tabindex:"-1"},[p("配置文件与数据目录 "),e("a",{class:"header-anchor",href:"#配置文件与数据目录","aria-label":'Permalink to "配置文件与数据目录"'},"​")],-1)),n(t),n(i),a[1]||(a[1]=c(`<h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><p>ICC-CE 的用户数据集中存放在数据目录下，典型结构如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据目录/</span></span>
<span class="line"><span>├── Settings.json          用户设置（下载页、工具栏、手势等全部配置）</span></span>
<span class="line"><span>├── Saves/                 自动保存的墨迹存档</span></span>
<span class="line"><span>│   └── &lt;演示文稿名&gt;/       按演示文稿分目录</span></span>
<span class="line"><span>├── Logs/                  运行日志</span></span>
<span class="line"><span>└── CrashLogs/             崩溃报告</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">快速定位</p><p>绿色版的数据目录通常就在程序所在文件夹内；安装版则位于用户目录下的应用数据文件夹中。 最可靠的办法是在设置界面中查找「打开数据文件夹」一类的入口。</p></div><h2 id="settings-json" tabindex="-1">Settings.json <a class="header-anchor" href="#settings-json" aria-label="Permalink to &quot;Settings.json&quot;">​</a></h2><p>所有设置项都序列化在这一个 JSON 文件里，按功能分区组织（画布、手势、形状识别、 PowerPoint、外观、启动、高级、自动化、安全等）。常用条目的说明见<a href="/website/cn/guide/settings">设置指南</a>。</p><p><strong>手工编辑注意事项：</strong></p><ul><li>编辑前请先完全退出 ICC-CE，否则退出时会用内存中的配置覆盖你的修改</li><li>保持 UTF-8 编码</li><li>键名大小写敏感，写错的键会被忽略而不是报错</li><li>改坏了可以直接删除该文件，程序下次启动会重新生成一份默认配置</li></ul><h2 id="墨迹存档" tabindex="-1">墨迹存档 <a class="header-anchor" href="#墨迹存档" aria-label="Permalink to &quot;墨迹存档&quot;">​</a></h2><p>自动保存的墨迹写入 <code>Saves</code> 目录。保存位置由自动化相关的设置项控制，可以改到网络盘或 U 盘上。</p><div class="warning custom-block"><p class="custom-block-title">路径迁移</p><p>早期版本的文档中提到过其他保存路径，现已统一到 <code>Saves</code>。若你从旧版本升级， 旧目录中的存档不会自动迁移，需要手动复制过来。</p></div><h2 id="日志与崩溃报告" tabindex="-1">日志与崩溃报告 <a class="header-anchor" href="#日志与崩溃报告" aria-label="Permalink to &quot;日志与崩溃报告&quot;">​</a></h2><ul><li><strong>Logs</strong>：记录启动、联动、识别等运行信息，排查问题时的首要参考</li><li><strong>CrashLogs</strong>：程序异常退出时生成，包含调用栈</li></ul><p>反馈 Bug 时请附上对应时间点的日志文件，能大幅加快定位速度。日志中可能包含演示文稿文件名， 介意的话可在发送前自行删改。</p><h2 id="备份与批量部署" tabindex="-1">备份与批量部署 <a class="header-anchor" href="#备份与批量部署" aria-label="Permalink to &quot;备份与批量部署&quot;">​</a></h2><p><strong>备份</strong>：复制 <code>Settings.json</code> 与 <code>Saves</code> 目录即可。</p><p><strong>批量部署</strong>：在一台机器上配置好之后，把 <code>Settings.json</code> 分发到其他机器的相同位置， 即可统一所有设备的工具栏布局与行为设置。配合绿色版可以做到整个文件夹直接拷贝。</p><div class="warning custom-block"><p class="custom-block-title">机房环境</p><p>部分机房使用还原卡或把安装目录设为只读。这种情况下请把数据目录指向不会被还原的分区， 否则每次重启都会丢失设置与墨迹。</p></div>`,18))])}const f=o(d,[["render",u]]);export{v as __pageData,f as default};
